op.a:
Function comprobar(){
var ek = event.keyCode;
if (ek > 47 && ek < 58 || ek ==44) {
event.keyCode="0";
alert("El campo solo puede contener números y la coma decimal");
event.focus; }
}

op.b:
Function comprobar(){
for (i=1,i>58) {
if (keycode(i) > 47 && keycode(i) < 58 || keycode(i)=44) {
alert("El campo solo puede contener números y la coma decimal");
event.focus; }
i =++1
}
}

op.c:
Function comprobar(){
var ek = Keycode.press if (ek > 47 && ek < 58) || (ek ==44) {
event.keyCode="0";
alert("El campo solo puede contener números y la coma decimal");
event.focus; }
}

op.d:
Function comprobar(ek){
for (i=1,i<58,i++) {
if (ek(i) > 47 && ek(i) < 58 || ek(i)=44) {
alert("El campo solo puede contener números y la coma o el punto decimal");
event.focus; }
}
}

