PREGUNTAS 11-28. A continuación, se presentan dos programas escritos en diferentes lenguajes de programación y se formulan
diferentes preguntas relacionadas con sus características y su ejecución.
Código: Programa 1
package Principal;
import java.io.IOException;
import java.io.PrintWriter;
import javax.servlet.ServletException;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.servlet.http.HttpSession;
public class Programa1 extends javax.servlet.http.HttpServlet implements javax.servlet.Servlet {
private static final long serialVersionUID = -283811616015383717L;
protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
PrintWriter pw=response.getWriter();
response.setContentType("text/html"); /* 1 */
pw.println("<html>");
pw.println("<head>");
pw.println("<title>");
pw.println("PROGRAMA1");
pw.println("</title");
pw.println("</head>");
pw.println("<body>");
pw.println("<h1 align=center>Programa1</h1>");
Servicio.getServicio().servir(pw,request.getSession());
pw.println("</body>");
pw.println("</html>");
}
}
class Servicio{
private static Servicio servicio;
private int c1=1;
private Servicio() {
servicio=this;
}
public static synchronized Servicio getServicio(){
if (servicio==null){
servicio=new Servicio();
}
return servicio;
}
public void servir(PrintWriter pw,HttpSession s)
{
int c2;
if (s.getAttribute("C2")!=null){
c2=(Integer)s.getAttribute("C2");
} else {
c2=1;
}
pw.println((c1++)+"<br>");
pw.println((c2++)+"<br>");
pw.println(new java.util.Date().toString()+"<br>");
s.setAttribute("C2", c2);
}
}
Código: Programa2
#include <stdio.h> /* 1 */
#include <stdlib.h>
void swap1 (char *a1, char *a2){
char *aux; /* 2 */
aux=a1;
a1=a2;
a2=aux;
}
void swap2 (char **a1, char **a2){
char **aux; /* 3 */
*aux=*a1;
*a1=*a2;
*a2=*aux;
}
int main(int nargs, char *args[]){
printf("Orden 1\n");
for (int i=1;i<nargs-1;i++){
for (int j=i+1;j<nargs;j++){
if (atoi(args[i])<atoi(args[j])) {
swap1(args[i],args[j]);
}
}
}
for (int i=1;i<nargs;i++){
printf("%3s",args[i]); /* 4 */
}
printf("\nOrden 2\n");
for (int i=1;i<nargs-1;i++){
for (int j=i+1;j<nargs;j++){
if (atoi(args[i])>atoi(args[j])) {
swap2(&args[i],&args[j]);
}
}
}
for (int i=1;i<nargs;i++){
printf("%3s",args[i]);
}
printf("\n");
}

