char **aux; /* 3 */
*aux=*a1;
*a1=*a2;
*a2=*aux;
}
int main(int nargs, char *args[]){
printf("Orden 1\n");
for (int i=1;i<nargs-1;i++){
for (int j=i+1;j<nargs;j++){
if (atoi(args[i])<atoi(args[j])) {
swap1(args[i],args[j]);
}
}
}
for (int i=1;i<nargs;i++){
printf("%3s",args[i]); /* 4 */
}
printf("\nOrden 2\n");
for (int i=1;i<nargs-1;i++){
for (int j=i+1;j<nargs;j++){
if (atoi(args[i])>atoi(args[j])) {
swap2(&args[i],&args[j]);
}
}
}
for (int i=1;i<nargs;i++){
printf("%3s",args[i]);
}
printf("\n");
}

